<script setup lang="ts">import type {GroupResult} from '../types/domain';import {num,pct} from '../utils/format';import {GEOMETRY_TYPES} from '../constants/enums';defineProps<{group:GroupResult}>()</script><template><div class="area-summary"><div><small>凸包面积</small><b>{{num(group.hull.area)}}<i>m²</i></b><span>{{GEOMETRY_TYPES[group.hull.geometry_type]}}</span></div><div><small>轴对齐框面积</small><b>{{num(group.axis_box.area)}}<i>m²</i></b><span>与x/y坐标轴平行</span></div><div><small>最小定向框面积</small><b>{{num(group.oriented_box.area)}}<i>m²</i></b><span>{{group.oriented_box.geometry_type==='point'?'点无方向':group.oriented_box.geometry_type==='line'?'线方向[0,180) '+num(group.oriented_box.angle_degrees)+'°':'面方向 '+num(group.oriented_box.angle_degrees)+'°'}} · 轴框冗余降低{{pct(group.axis_reduction_fraction)}}</span></div></div></template>